  class phone_soc_mesh_gpio_blk extends uvm_reg_block;
    `uvm_object_utils(phone_soc_mesh_gpio_blk)
    rand phone_soc_mesh_gpio_blk_id ID;
    rand phone_soc_mesh_gpio_blk_irq_status IRQ_STATUS;
    rand phone_soc_mesh_gpio_blk_irq_enable IRQ_ENABLE;
    rand phone_soc_mesh_gpio_blk_flags FLAGS;
    rand phone_soc_mesh_gpio_blk_scratch SCRATCH;
    rand phone_soc_mesh_gpio_blk_oe OE;
    rand phone_soc_mesh_gpio_blk_out OUT;
    rand phone_soc_mesh_gpio_blk_in IN;
    function new(string name = "phone_soc_mesh_gpio_blk");
      super.new(name, UVM_NO_COVERAGE);
    endfunction
    virtual function void build();
      default_map = create_map("map", 0, 4, UVM_LITTLE_ENDIAN, 1);
      ID = phone_soc_mesh_gpio_blk_id::type_id::create("ID");
      ID.configure(this);
      ID.build();
      default_map.add_reg(ID, 'h000, "RO");
      IRQ_STATUS = phone_soc_mesh_gpio_blk_irq_status::type_id::create("IRQ_STATUS");
      IRQ_STATUS.configure(this);
      IRQ_STATUS.build();
      default_map.add_reg(IRQ_STATUS, 'h004, "RW");
      IRQ_ENABLE = phone_soc_mesh_gpio_blk_irq_enable::type_id::create("IRQ_ENABLE");
      IRQ_ENABLE.configure(this);
      IRQ_ENABLE.build();
      default_map.add_reg(IRQ_ENABLE, 'h008, "RW");
      FLAGS = phone_soc_mesh_gpio_blk_flags::type_id::create("FLAGS");
      FLAGS.configure(this);
      FLAGS.build();
      default_map.add_reg(FLAGS, 'h00C, "RO");
      uvm_resource_db#(bit)::set({"REG::", FLAGS.get_full_name()}, "NO_REG_TESTS", 1, this);
      SCRATCH = phone_soc_mesh_gpio_blk_scratch::type_id::create("SCRATCH");
      SCRATCH.configure(this);
      SCRATCH.build();
      default_map.add_reg(SCRATCH, 'h010, "RW");
      OE = phone_soc_mesh_gpio_blk_oe::type_id::create("OE");
      OE.configure(this);
      OE.build();
      default_map.add_reg(OE, 'h014, "RW");
      OUT = phone_soc_mesh_gpio_blk_out::type_id::create("OUT");
      OUT.configure(this);
      OUT.build();
      default_map.add_reg(OUT, 'h018, "RW");
      uvm_resource_db#(bit)::set({"REG::", OUT.get_full_name()}, "NO_REG_TESTS", 1, this);
      IN = phone_soc_mesh_gpio_blk_in::type_id::create("IN");
      IN.configure(this);
      IN.build();
      default_map.add_reg(IN, 'h01C, "RO");
      uvm_resource_db#(bit)::set({"REG::", IN.get_full_name()}, "NO_REG_TESTS", 1, this);
      lock_model();
    endfunction
  endclass

